/// 9, 10 ve 11. sınıf hazır kartları — Türkiye Yüzyılı Maarif Modeli
/// konularından, önceki kart paketlerinde karşılığı az olanlar için
/// hazırlanmıştır. Kart kimliği `<konu id>-k<sıra>` biçimindedir; böylece
/// kart doğrudan sınıf müfredatındaki konusuna bağlanır.
library;

import '../../data/models/flash_kart.dart';
import 'sinif_mufredati.dart';

const _desteler = {
  'Matematik': 'matematik',
  'Fizik': 'fizik',
  'Kimya': 'kimya',
  'Biyoloji': 'biyoloji',
  'Türk Dili ve Edebiyatı': 'edebiyat',
  'Tarih': 'tarih',
  'Coğrafya': 'cografya',
  'Felsefe': 'felsefe',
};

/// [konuId] konusunun [sira]. kartı. Deste ve ünite adı konudan alınır.
FlashKart _k(String konuId, int sira, String on, String arka, [String? ipucu]) {
  final k = sinifKonusuBul(konuId)!;
  return FlashKart(id: '$konuId-k$sira', ders: _desteler[k.ders]!, unite: k.baslik, on: on, arka: arka, ipucu: ipucu);
}

