  _k('s9-tar-03', 2, "Anadolu'da ilk yerleşmeler", "Göbeklitepe (Şanlıurfa): bilinen en eski anıtsal tapınak alanlarından\nÇatalhöyük (Konya): ilk şehir yerleşmelerinden\nÇayönü (Diyarbakır): ilk tarım köylerinden", "Göbeklitepe – Çatalhöyük – Çayönü"),
  _k('s9-tar-05', 1, "Mezopotamya ve Mısır'da bilim", "Mezopotamya: çivi yazısı, Ay yılı takvimi, altmışlık sayı sistemi, ziggurat.\nMısır: hiyeroglif, Güneş yılı takvimi, mumyalama ile tıp, piramit ile geometri.", "Ay yılı – Güneş yılı"),
  _k('s9-tar-05', 2, "Anadolu uygarlıklarının katkıları", "Hititler: anal (yıllıklar), Kadeş Antlaşması, Pankuş meclisi\nLidyalılar: para, Kral Yolu\nFrigler: tarım kanunları, tapates (halı)\nUrartular: su kanalları, madencilik\nİyonlar: özgür düşünce, bilim", "Lidya = para"),
  _k('s9-tar-07', 1, "Kavimler Göçü ve sonuçları", "Hunların batıya ilerlemesiyle Germen kavimleri göç etti. Sonuçları: Roma ikiye ayrıldı, Batı Roma yıkıldı, feodalite doğdu, Avrupa Hun Devleti kuruldu, İlk Çağ bitti.", "375 – Orta Çağ başlar"),
  _k('s9-tar-07', 2, "Türk göçlerinin nedenleri", "İklim değişikliği ve kuraklık, otlakların yetersizliği, nüfus artışı, boylar arası mücadeleler, Çin ve Moğol baskısı, yeni yurtlar edinme isteği.", "Kuraklık + baskı"),
  _k('s9-tar-09', 1, "İpek Yolu ve Baharat Yolu", "İpek Yolu: Çin → Orta Asya → Anadolu → Avrupa.\nBaharat Yolu: Hindistan → Basra Körfezi/Kızıldeniz → Akdeniz limanları.\nCoğrafi Keşiflerle önemlerini yitirdiler.", "Çin'den ipek, Hint'ten baharat"),
  _k('s9-tar-09', 2, "Kervansaray", "Ticaret yolları üzerinde tüccar ve yolcuların konakladığı yapılardır. Güvenlik, barınma ve ticaretin sürekliliğini sağlamış; Selçuklular döneminde yaygınlaşmıştır.", "Yol güvenliği"),
  _k('s9-tar-10', 1, "Orta Çağ İslam dünyasında bilim", "Beytü'l-Hikme (Bağdat): çeviri ve bilim merkezi\nHarezmî: cebir\nİbn-i Sina: tıp (El-Kanun fi't-Tıb)\nBîrûnî: astronomi, coğrafya\nFarabi: felsefe, müzik\nİbnü'l-Heysem: optik", "Bilgin – alan"),
  _k('s9-tar-10', 2, "Skolastik düşünce", "Orta Çağ Avrupa'sında kilisenin öğretilerini tartışılmaz kabul eden; akıl, gözlem ve deneyi geri plana iten düşünce sistemidir. Rönesans ve Reform ile sarsılmıştır.", "Dogmaya dayanır"),
  _k('s9-cog-01', 1, "Coğrafyanın bölümleri", "Fiziki coğrafya: jeomorfoloji, klimatoloji, hidrografya, biyocoğrafya.\nBeşerî coğrafya: nüfus, yerleşme, kültür, siyasi coğrafya.\nEkonomik coğrafya: tarım, sanayi, ulaşım, turizm.", "Fiziki – beşerî – ekonomik"),
  _k('s9-cog-01', 2, "Coğrafyanın ilkeleri", "Dağılış: olay nerede görülür?\nNedensellik: neden orada?\nKarşılıklı ilgi (bağlantı): başka olaylarla ilişkisi nedir?", "Nerede – neden – neyle ilgili"),
  _k('s9-cog-03', 1, "Türkiye'nin özel konumunun sonuçları", "Asya, Avrupa ve Afrika arasında köprü; üç tarafı denizlerle çevrili; boğazlara sahip; yükseltisi doğuya doğru artar; enerji ve ticaret yollarının kavşağındadır.", "Kıtalar arası köprü"),
  _k('s9-cog-04', 1, "Coğrafi Bilgi Sistemleri (CBS)", "Konuma dayalı verileri toplayan, saklayan, analiz eden ve haritalayan sistemdir. Bileşenleri: donanım, yazılım, veri, insan, yöntem.", "5 bileşen"),
  _k('s9-cog-04', 2, "Uzaktan algılama ve GPS", "Uzaktan algılama: uydu ve hava araçlarıyla yeryüzünden temas etmeden veri toplama.\nGPS: uydular aracılığıyla konum (enlem, boylam, yükselti) belirleme.", "Uydu görüntüsü – konum"),
  _k('s9-cog-07', 1, "Küresel iklim değişikliği", "Sera gazlarının (CO₂, metan) insan etkisiyle artması sonucu ortalama sıcaklıkların yükselmesidir. Sonuçları: buzulların erimesi, deniz seviyesinin yükselmesi, kuraklık, aşırı hava olayları.", "Sera gazı ↑ sıcaklık ↑"),
  _k('s9-cog-07', 2, "Geçmiş iklimlerin kanıtları", "Buzul sondajları (karotlar), ağaç halkaları, fosil polenler, göl ve deniz çökelleri, mercan iskeletleri geçmişteki sıcaklık ve yağış koşulları hakkında bilgi verir.", "Buzul – ağaç halkası – polen"),
  _k('s9-cog-09', 1, "Nüfus piramidi nasıl yorumlanır?", "Tabanı geniş: doğum oranı yüksek, genç nüfus fazla (gelişmemiş).\nTabanı dar, üstü geniş: doğum oranı düşük, yaşlı nüfus fazla (gelişmiş).\nGövdesi şişkin: çalışma çağındaki nüfus fazla.", "Tabana bak"),
  _k('s9-cog-09', 2, "Nüfus politikaları", "Nüfus artış hızını artırmaya yönelik: yaşlanan ülkeler (Almanya, Japonya).\nAzaltmaya yönelik: hızlı artan ülkeler (Hindistan).\nNiteliği iyileştirmeye yönelik: eğitim ve sağlık yatırımları.", "Artır – azalt – niteliği yükselt"),
  _k('s9-cog-10', 1, "Ekonomik faaliyetleri etkileyen faktörler", "Doğal: iklim, yer şekilleri, su kaynakları, toprak, yer altı kaynakları.\nBeşerî: nüfus ve iş gücü, sermaye, teknoloji, ulaşım, pazar, devlet politikaları.", "Doğal + beşerî"),
  _k('s9-cog-10', 2, "Birincil, ikincil ve üçüncül faaliyetler", "Birincil: ham madde üretimi (tarım, hayvancılık, ormancılık, madencilik).\nİkincil: ham maddenin işlenmesi (sanayi).\nÜçüncül: hizmetler (ticaret, ulaşım, eğitim, sağlık, turizm).", "Üret – işle – hizmet et"),
  _k('s9-cog-12', 1, "Bölge türleri", "Şekilsel bölge: tek bir özelliğe göre (iklim, bitki örtüsü, nüfus yoğunluğu).\nİşlevsel bölge: bir merkez ve etki alanına göre (bir limanın art bölgesi, bir şehrin hizmet alanı).", "Şekilsel – işlevsel"),
  // ═══ 10. SINIF ══════════════════════════════════════════════════════
  _k('s10-mat-01', 1, "Dik üçgende trigonometrik oranlar", "sin α = karşı / hipotenüs\ncos α = komşu / hipotenüs\ntan α = karşı / komşu\ncot α = komşu / karşı", "Karşı – komşu – hipotenüs"),
  _k('s10-mat-01', 2, "Özel açıların trigonometrik değerleri", "sin 30° = 1/2, cos 30° = √3/2\nsin 45° = cos 45° = √2/2\nsin 60° = √3/2, cos 60° = 1/2\ntan 45° = 1\nsin²α + cos²α = 1", "30 – 45 – 60"),
  _k('s10-mat-04', 1, "Sinüs teoremi", "a / sin A = b / sin B = c / sin C = 2R\n(R: çevrel çemberin yarıçapı)\nBir kenar ile iki açı ya da iki kenar ile birinin karşısındaki açı biliniyorsa kullanılır.", "Kenar / karşı açının sinüsü"),
  _k('s10-mat-04', 2, "Kosinüs teoremi", "a² = b² + c² − 2bc · cos A\nİki kenar ile aralarındaki açı ya da üç kenar biliniyorsa kullanılır. A = 90° için Pisagor bağıntısına dönüşür.", "İki kenar + aradaki açı"),
  _k('s10-mat-05', 1, "İki yönlü tablo", "İki kategorik değişkenin birlikte dağılımını gösterir. Satır ve sütun toplamları marjinal, hücreler ortak sıklıklardır. Koşullu oranlar karşılaştırılarak ilişki yorumlanır.", "Satır × sütun"),
  _k('s10-mat-05', 2, "Kategorik ve nicel değişken", "Kategorik (nitel): sınıflara ayrılır, sayıyla ölçülmez (göz rengi, kan grubu).\nNicel: sayıyla ölçülür (boy, puan, yaş).", "Sınıf mı, sayı mı?"),
  _k('s10-mat-06', 1, "Bir sayının pozitif bölen sayısı nasıl bulunur?", "n = aˣ · bʸ · cᶻ (asal çarpanlara ayrılmış) ise pozitif bölen sayısı (x + 1)(y + 1)(z + 1) olur.", "Üslerin bir fazlasını çarp"),
  _k('s10-mat-06', 2, "Asal çarpanlara ayırma", "Her doğal sayı (1'den büyük) asal sayıların çarpımı olarak tek türlü yazılır. Örnek: 360 = 2³ · 3² · 5.", "Aritmetiğin temel teoremi"),
  _k('s10-mat-07', 1, "EBOB ve EKOK ilişkisi", "a · b = EBOB(a, b) · EKOK(a, b)\nAralarında asal iki sayının EBOB'u 1, EKOK'u çarpımlarıdır.\nBölme-parçalama problemlerinde EBOB, birlikte tekrar etme problemlerinde EKOK kullanılır.", "Çarpım = EBOB · EKOK"),
  _k('s10-mat-11', 1, "Karekök fonksiyonu", "f(x) = √x; tanım kümesi [0, ∞), görüntü kümesi [0, ∞), artandır. f(x) = √(x − a) + b grafiği, a birim sağa ve b birim yukarı ötelenmiş hâlidir.", "Kök içi ≥ 0"),
  _k('s10-mat-11', 2, "Rasyonel fonksiyon", "İki polinomun oranı biçimindedir. Paydayı sıfır yapan değerlerde tanımsızdır; bu değerlerde düşey asimptot bulunabilir. f(x) = 1/x'in grafiği hiperboldür.", "Payda ≠ 0"),
  _k('s10-mat-12', 1, "Ters fonksiyon", "f bire bir ve örten ise tersi vardır. f(a) = b ⟺ f⁻¹(b) = a.\nf(x) = ax + b ise f⁻¹(x) = (x − b) / a.\nf ile f⁻¹'in grafikleri y = x doğrusuna göre simetriktir.", "x ile y'nin yerini değiştir"),
  _k('s10-mat-12', 2, "Ters fonksiyonun var olma koşulu", "Bir fonksiyonun tersinin de fonksiyon olması için bire bir ve örten olması gerekir. f(x) = x² gerçek sayılarda bire bir değildir; tanım kümesi [0, ∞) alınırsa tersi f⁻¹(x) = √x olur.", "Bire bir ve örten"),
  _k('s10-mat-13', 1, "İkinci dereceden denklemin kökleri", "ax² + bx + c = 0 için Δ = b² − 4ac.\nΔ > 0: iki farklı gerçek kök\nΔ = 0: çakışık (tek) kök\nΔ < 0: gerçek kök yok\nKökler toplamı −b/a, çarpımı c/a.", "Diskriminant"),
  _k('s10-mat-13', 2, "İkinci dereceden eşitsizlik", "a > 0 iken (x − x₁)(x − x₂) < 0 eşitsizliği kökler arasında, > 0 eşitsizliği köklerin dışında sağlanır. İşaret tablosuyla çözülür.", "Kökler arası zıt işaret"),
  _k('s10-mat-15', 1, "İki nokta arası uzaklık ve orta nokta", "A(x₁, y₁), B(x₂, y₂) için\n|AB| = √((x₂ − x₁)² + (y₂ − y₁)²)\nOrta nokta: ((x₁ + x₂)/2, (y₁ + y₂)/2)", "Pisagor'un koordinatlı hâli"),
  _k('s10-mat-15', 2, "Koordinat düzleminde bölgeler", "I. bölge: (+, +)\nII. bölge: (−, +)\nIII. bölge: (−, −)\nIV. bölge: (+, −)\nEksenler üzerindeki noktalar hiçbir bölgeye ait değildir.", "Saat yönünün tersine"),
  _k('s10-mat-17', 1, "Koşullu olasılık", "P(A | B) = P(A ∩ B) / P(B)\nB olayının gerçekleştiği bilindiğinde örnek uzay B'ye daralır.", "Örnek uzay daralır"),
  _k('s10-mat-17', 2, "Bağımsız olaylar", "Birinin gerçekleşmesi diğerinin olasılığını etkilemiyorsa olaylar bağımsızdır: P(A ∩ B) = P(A) · P(B) ve P(A | B) = P(A).", "Etkilemiyorsa çarp"),
  _k('s10-fiz-02', 1, "Sabit ivmeli hareket bağıntıları", "v = v₀ + a · t\nx = v₀ · t + (1/2) · a · t²\nv² = v₀² + 2 · a · x", "Üç temel bağıntı"),
  _k('s10-fiz-02', 2, "Hareket grafikleri", "Konum–zaman grafiğinin eğimi hızı verir.\nHız–zaman grafiğinin eğimi ivmeyi, altındaki alan yer değiştirmeyi verir.\nİvme–zaman grafiğinin altındaki alan hız değişimini verir.", "Eğim ve alan"),
  _k('s10-fiz-04', 1, "Mekanik enerji", "Kinetik: Ek = (1/2) · m · v²\nKütle çekim potansiyel: Ep = m · g · h\nEsneklik potansiyel: Ep = (1/2) · k · x²\nSürtünme yoksa mekanik enerji korunur.", "Ek + Ep = sabit"),
  _k('s10-fiz-04', 2, "Enerjinin korunumu", "Enerji yoktan var edilemez, vardan yok edilemez; yalnızca bir türden diğerine dönüşür. Sürtünmeli ortamda mekanik enerjinin bir kısmı ısıya dönüşür.", "Dönüşür, kaybolmaz"),
  _k('s10-fiz-05', 1, "Yenilenebilir ve yenilenemez enerji kaynakları", "Yenilenebilir: güneş, rüzgâr, hidroelektrik, jeotermal, biyokütle, dalga.\nYenilenemez: kömür, petrol, doğal gaz, nükleer.", "Tükenir mi?"),
  _k('s10-fiz-05', 2, "Verim", "Verim = (alınan faydalı enerji / verilen toplam enerji) · 100. Hiçbir makinenin verimi %100 olamaz; enerjinin bir kısmı ısı olarak kaybedilir.", "Hep %100'den az"),
  _k('s10-fiz-07', 1, "Ohm yasası ve birimler", "Bir iletkenin uçları arasındaki potansiyel farkının akıma oranı sabittir: R = V / I.\nBirimler: volt (V), amper (A), ohm (Ω).", "V = I · R"),
  _k('s10-fiz-07', 2, "İletkenin direncini etkileyen etkenler", "R = ρ · L / A\nUzunluk arttıkça direnç artar, kesit alanı arttıkça azalır; öz direnç (ρ) maddenin cinsine bağlıdır. Sıcaklık arttıkça metallerin direnci artar.", "Uzun ve ince tel → büyük direnç"),
  _k('s10-fiz-08', 1, "Dirençlerin bağlanması", "Seri: Reş = R₁ + R₂; akımlar eşit, gerilim paylaşılır.\nParalel: 1/Reş = 1/R₁ + 1/R₂; gerilimler eşit, akım paylaşılır.", "Seri akım aynı, paralel gerilim aynı"),
  _k('s10-fiz-08', 2, "Üreteçlerin bağlanması", "Seri: gerilimler toplanır, devreden geçen akım artar, piller çabuk tükenir.\nParalel (özdeş): gerilim tek pilinkine eşittir, pillerin ömrü uzar.", "Seri güç, paralel ömür"),
  _k('s10-fiz-09', 1, "Elektrik güvenliği", "Sigorta: aşırı akımda devreyi keser.\nTopraklama: kaçak akımı toprağa aktarır.\nKaçak akım rölesi: kaçak algılandığında devreyi açar.\nIslak elle cihaza dokunulmaz.", "Sigorta – topraklama – röle"),
  _k('s10-fiz-09', 2, "Kısa devre", "Akımın dirençsiz (çok düşük dirençli) bir yoldan geçmesidir. Akım çok büyür, teller ısınır ve yangın çıkabilir. Sigorta devreyi keserek korur.", "Direnç yok, akım çok"),
  _k('s10-fiz-11', 1, "Dalgaların sınıflandırılması", "Taşıdığı enerjiye göre: mekanik (ortam gerekir) ve elektromanyetik (boşlukta yayılır).\nTitreşim doğrultusuna göre: enine (dik) ve boyuna (paralel).", "Ses boyuna, ışık enine"),
  _k('s10-fiz-11', 2, "Ses dalgalarının özellikleri", "Mekanik ve boyuna dalgadır; boşlukta yayılmaz. En hızlı katılarda, en yavaş gazlarda yayılır. Yükseklik frekansa, şiddet genliğe bağlıdır.", "Boşlukta ses yok"),
  _k('s10-fiz-12', 1, "Su dalgalarında yansıma ve kırılma", "Frekans kaynağa bağlıdır, ortam değişse de değişmez. Derin sudan sığ suya geçen dalganın hızı ve dalga boyu azalır.", "Frekans sabit"),
  _k('s10-fiz-12', 2, "Rezonans", "Zorlayıcı etkinin frekansı sistemin doğal frekansına eşit olduğunda titreşim genliğinin büyümesidir. Depremde binaların yıkılması, salıncağın uygun anda itilmesi örnektir.", "Frekanslar çakışır"),
  _k('s10-kim-03', 1, "Kimyasal tepkimelerde korunan nicelikler", "Atom türü ve sayısı, toplam kütle, toplam yük ve toplam enerji korunur. Molekül sayısı, mol sayısı ve hacim korunmayabilir.", "Atom ve kütle korunur"),
  _k('s10-kim-03', 2, "Stokiyometrik hesaplama adımları", "1. Denklemi denkleştir.\n2. Verilen miktarı mole çevir.\n3. Katsayı oranıyla istenen maddenin molünü bul.\n4. Molü istenen birime çevir.", "Her şey mol üzerinden"),
  _k('s10-kim-05', 1, "İdeal gaz denklemi (PV = nRT)", "P · V = n · R · T\nP: basınç (atm), V: hacim (L), n: mol, T: mutlak sıcaklık (K), R = 0,082 L·atm/(mol·K).\nNormal koşullarda 1 mol gaz 22,4 L hacim kaplar.", "PV = nRT"),
  _k('s10-kim-05', 2, "Gazların yayılma hızı (Graham yasası)", "Aynı koşullarda gazların yayılma hızı, mol kütlelerinin karekökü ile ters orantılıdır: v₁ / v₂ = √(M₂ / M₁). Hafif gaz daha hızlı yayılır.", "Hafif olan hızlı"),
  _k('s10-kim-06', 1, "Çözünürlüğe etki eden etkenler", "Çözücü ve çözünenin cinsi (benzer benzeri çözer), sıcaklık (katılarda genellikle artırır, gazlarda azaltır), basınç (yalnızca gazlarda; arttıkça çözünürlük artar).", "Gaz: soğuk ve basınçlı"),
  _k('s10-kim-08', 1, "Koligatif özellikler nelerdir?", "Çözünen taneciklerin sayısına bağlı özelliklerdir: kaynama noktası yükselmesi, donma noktası alçalması, buhar basıncı düşmesi, ozmotik basınç.", "Tanecik sayısına bağlı"),
  _k('s10-kim-08', 2, "Koligatif özelliklerin günlük hayat örnekleri", "Kışın yollara tuz dökülmesi (donma noktası düşer), araç radyatörüne antifriz konması, makarna suyuna tuz atılınca kaynama noktasının biraz yükselmesi.", "Tuz – antifriz"),
  _k('s10-kim-09', 1, "Atmosferdeki küresel sorunlar", "Sera etkisi: CO₂, CH₄ → küresel ısınma\nAsit yağmuru: SO₂ ve azot oksitler\nOzon incelmesi: kloroflorokarbonlar (CFC)", "Gaz – sorun eşleştir"),
  _k('s10-kim-09', 2, "Mikro ölçekli deney", "Çok az miktarda kimyasalla yapılan deneydir. Daha az atık, daha düşük maliyet ve daha güvenli çalışma sağlar; yeşil kimya ilkeleriyle uyumludur.", "Az madde, az atık"),
  _k('s10-biy-01', 1, "ATP", "Adenin bazı + riboz şekeri + üç fosfat grubundan oluşur. Hücrede enerji aktarımını sağlar; depolanmaz, hücreler arasında taşınmaz, her hücre kendi ATP'sini üretir.", "Hücrenin enerji parası"),
  _k('s10-biy-01', 2, "Fosforilasyon çeşitleri", "Substrat düzeyinde: tüm canlılarda, sitoplazmada.\nOksidatif: oksijenli solunumda ETS'de.\nFotofosforilasyon: ışık enerjisiyle, kloroplastta.\nKemofosforilasyon: kemosentezde.", "ADP + P → ATP"),
  _k('s10-biy-04', 1, "Oksijenli solunum: evreler ve gerçekleştiği yerler", "Glikoliz: sitoplazma, net 2 ATP\nSitrik asit (Krebs) döngüsü: mitokondri matriksi\nElektron taşıma sistemi (ETS): mitokondri iç zarı, en çok ATP; son elektron alıcısı oksijen", "Glikoliz – Krebs – ETS"),
  _k('s10-biy-04', 2, "Etil alkol ve laktik asit fermantasyonu", "Oksijen kullanılmadan glikozun kısmen yıkılmasıdır; net 2 ATP elde edilir.\nEtil alkol fermantasyonu: etil alkol + CO₂ (maya)\nLaktik asit fermantasyonu: laktik asit (kas hücresi, yoğurt bakterileri)", "Oksijensiz, 2 ATP"),
  _k('s10-biy-06', 1, "Besin zinciri ve enerji akışı", "Üretici → birincil tüketici → ikincil tüketici → üçüncül tüketici. Her basamakta enerjinin yaklaşık %10'u aktarılır; madde döngüseldir, enerji akışı tek yönlüdür.", "%10 kuralı"),
  _k('s10-biy-06', 2, "Biyolojik birikim", "Parçalanamayan zehirli maddelerin (DDT, ağır metaller) besin zincirinde üst basamaklara doğru artarak birikmesidir. En çok son tüketiciler etkilenir.", "Yukarı çıktıkça artar"),
  _k('s10-biy-07', 1, "Azot döngüsü", "Azot bağlanması: N₂ → amonyak (bakteriler, şimşek)\nNitrifikasyon: amonyak → nitrit → nitrat\nDenitrifikasyon: nitrat → N₂ (toprak azotça fakirleşir)\nAmonifikasyon: organik artıklar → amonyak", "Bitkiler azotu nitrat olarak alır"),
  _k('s10-biy-07', 2, "Karbon ve su döngüsü", "Karbon: fotosentez atmosferdeki CO₂'yi azaltır; solunum, yanma ve çürüme artırır.\nSu: buharlaşma ve terleme → yoğuşma → yağış → yüzey ve yer altı akışı.", "Fotosentez alır, solunum verir"),
  _k('s10-biy-08', 1, "Ekolojik ayak izi", "Bir bireyin ya da toplumun tükettiği kaynakları üretmek ve atıklarını yok etmek için gereken verimli alanın ölçüsüdür. Karbon ayak izi ve su ayak izi alt bileşenleridir.", "Doğaya bıraktığımız iz"),
  _k('s10-biy-08', 2, "Sürdürülebilirlik", "Bugünün ihtiyaçlarını, gelecek kuşakların ihtiyaçlarını karşılama imkânını ortadan kaldırmadan karşılamaktır. Geri dönüşüm, yenilenebilir enerji ve bilinçli tüketimle desteklenir.", "Gelecek kuşakları düşün"),
  _k('s10-edb-04', 1, "Saf (öz) şiir", "“Şiir, şiir içindir.” anlayışıdır. Ahenk, musiki ve biçim kusursuzluğu önemsenir; imge ve çağrışıma dayanır, didaktik amaç güdülmez.", "Ahenk ve biçim"),
  _k('s10-edb-04', 2, "Saf şiirin temsilcileri", "Ahmet Haşim, Yahya Kemal Beyatlı, Ahmet Hamdi Tanpınar, Necip Fazıl Kısakürek, Cahit Sıtkı Tarancı, Ahmet Muhip Dıranas, Ziya Osman Saba.", "Haşim – Yahya Kemal – Tanpınar"),
  _k('s10-edb-05', 1, "Türk destanları hangi boylara aittir?", "Sakalar: Alp Er Tunga, Şu\nHunlar: Oğuz Kağan\nGöktürkler: Bozkurt, Ergenekon\nUygurlar: Türeyiş, Göç\nKırgızlar: Manas", "Boy – destan"),
  _k('s10-edb-05', 2, "Halk hikâyesi", "Destandan modern hikâyeye geçiş türüdür. Nazım-nesir karışıktır, âşıklarca anlatılır; aşk ve kahramanlık konuları işlenir. Kerem ile Aslı, Köroğlu, Ferhat ile Şirin.", "Nazım + nesir"),
  _k('s10-edb-07', 1, "Dede Korkut Hikâyeleri'nin yapısı", "Bir ön söz ve on iki hikâyeden oluşur; destandan halk hikâyesine geçiş ürünüdür. Oğuzların yaşamını anlatır; her hikâyenin sonunda Dede Korkut dua eder ve ad koyar.", "12 hikâye, Oğuz boyları"),
  _k('s10-tar-02', 1, "Selçuklularda devlet teşkilatı", "Divan-ı Saltanat: devlet işlerinin görüşüldüğü büyük divan (başkanı vezir)\nİkta: toprak gelirinin hizmet karşılığı verilmesi\nAtabey: meliklerin eğitmeni\nGulam sistemi: saray ve ordu için asker yetiştirme", "İkta → Osmanlı'da tımar"),
  _k('s10-tar-02', 2, "Türk-İslam devletlerinde veraset", "“Ülke hanedanın ortak malıdır” anlayışı geçerlidir. Bu anlayış taht kavgalarına ve devletlerin kısa sürede parçalanmasına yol açmıştır.", "Ortak mal → taht kavgası"),
  _k('s10-tar-03', 1, "Ahilik", "Ahi Evran'ın öncülüğünde kurulan esnaf ve zanaatkâr dayanışma örgütüdür. Meslek ahlakını, kaliteyi ve fiyat denetimini sağlamış; Anadolu'nun Türkleşmesine katkıda bulunmuştur.", "Esnaf dayanışması"),
  _k('s10-tar-03', 2, "Selçuklularda ticareti geliştiren önlemler", "Kervansaraylar, devlet sigortası (zararın karşılanması), düşük gümrük vergisi, Sinop – Antalya – Alanya limanlarının alınması, yabancı tüccarlara ayrıcalıklar.", "Kervansaray + sigorta"),
  _k('s10-tar-06', 1, "Osmanlı'da tımar sistemi", "Dirlik topraklarının gelirinin hizmet karşılığı asker ve görevlilere verilmesidir. Hazineden para çıkmadan ordu (tımarlı sipahi) beslenir, üretim sürer, taşrada güvenlik sağlanır.", "Topraklı süvari"),
  _k('s10-tar-06', 2, "Osmanlı hukuku", "Şeri hukuk: İslam hukukuna dayanır.\nÖrfi hukuk: Türk töresine ve padişah fermanlarına (kanunname) dayanır.\nDavalara kadılar bakar.", "Şeri + örfi"),
  _k('s10-tar-07', 1, "İskân politikası", "Fethedilen bölgelere Anadolu'dan Türkmenlerin yerleştirilmesidir. Amaç: fetihleri kalıcı kılmak, bölgeyi Türkleştirmek, konargöçerleri yerleşik hayata geçirmek.", "Yerleştir, kalıcı kıl"),
  _k('s10-tar-07', 2, "İstimalet politikası", "Fethedilen yerlerdeki halka hoşgörülü ve adil davranılması, din ve vicdan özgürlüğünün tanınması, vergilerin hafifletilmesidir. Balkan fetihlerini kolaylaştırmıştır.", "Gönül kazanma"),
  _k('s10-tar-08', 1, "Osmanlı'da ilk medreseler ve bilginler", "İlk medrese: İznik, Orhan Bey dönemi (müderrisi Davud-ı Kayserî).\nMolla Fenari, Akşemseddin, Ali Kuşçu kuruluş ve yükselme döneminin önemli bilginleridir.", "İznik Medresesi"),
  _k('s10-tar-08', 2, "Tekke ve zaviyelerin işlevi", "Dervişlerin kurduğu zaviyeler fethedilen yerlerin şenlenmesini, yolların güvenliğini, halkın kaynaşmasını ve İslam'ın yayılmasını sağlamıştır.", "Kolonizatör dervişler"),
  _k('s10-tar-11', 1, "Coğrafi Keşiflerin Osmanlı'ya etkileri", "İpek ve Baharat yolları ile Akdeniz limanları önemini yitirdi; gümrük gelirleri azaldı. Amerika'dan gelen değerli madenler akçenin değerini düşürdü, fiyatlar arttı.", "Ticaret okyanuslara kaydı"),
  _k('s10-tar-11', 2, "Celâlî isyanları", "17. yüzyılda Anadolu'da ağır vergiler, tımar sisteminin bozulması ve ekonomik sıkıntılar nedeniyle çıkmıştır. Köylü toprağını bırakmış (Büyük Kaçgun), üretim düşmüştür.", "Anadolu – ekonomik neden"),
  _k('s10-cog-01', 1, "CBS'nin kullanım alanları", "Şehir planlama, afet yönetimi, ulaşım ve navigasyon, tarım, ormancılık, çevre izleme, sağlık ve eğitim hizmetlerinin planlanması.", "Katmanları üst üste bindir"),
  _k('s10-cog-01', 2, "Coğrafi bakış", "Olayları mekân üzerinden değerlendirmektir: nerede, neden orada, nasıl dağılmış, çevresiyle ilişkisi ne, nasıl değişiyor sorularını sorar.", "Nerede ve neden orada?"),
  _k('s10-cog-02', 1, "Levha sınırları", "Uzaklaşan (ıraksayan): okyanus ortası sırtları, rift vadileri\nYaklaşan (yakınsayan): kıvrım dağları, okyanus çukurları, volkanizma\nYanal kayan (transform): fay hatları ve depremler", "Uzaklaş – yaklaş – kay"),
  _k('s10-cog-06', 1, "Afet öncesi, sırası ve sonrası", "Öncesi: risk azaltma, aile afet planı, afet çantası, sağlam yapı.\nSırası: çök-kapan-tutun, panik yapmama.\nSonrası: toplanma alanına gitme, resmî duyuruları izleme.", "Hazırlık hayat kurtarır"),
  _k('s10-cog-06', 2, "Afetlere dirençli şehir", "Zemin etüdüne uygun yapılaşma, yapı denetimi, riskli binaların dönüştürülmesi, toplanma alanları, erken uyarı sistemleri ve toplumsal afet eğitimi.", "Zemin + yapı + eğitim"),
  _k('s10-cog-07', 1, "Türk kültürünün yayılış alanı", "Orta Asya'dan başlayarak Anadolu, Kafkasya, Balkanlar, Orta Doğu ve Doğu Avrupa'ya uzanır. Göçler ve kurulan devletler kültürün geniş bir coğrafyaya taşınmasını sağlamıştır.", "Orta Asya'dan Balkanlara"),
  _k('s10-cog-07', 2, "Somut ve somut olmayan kültürel miras", "Somut: cami, köprü, kervansaray, konut, arkeolojik alan.\nSomut olmayan: Nevruz, âşıklık geleneği, Karagöz, meddahlık, Türk kahvesi kültürü, ebru sanatı.", "Yapı mı, gelenek mi?"),
  _k('s10-fel-03', 1, "Varlık felsefesinin temel soruları", "Varlık var mıdır? (Nihilizm: yoktur; realizm: vardır)\nVarlığın ana maddesi nedir? (idea, madde, hem madde hem ruh – düalizm)\nEvrende bir amaç var mıdır?", "Var mı – nedir?"),
  // ═══ 11. SINIF ══════════════════════════════════════════════════════
  _k('s11-mat-01', 1, "Saçılım grafiği ve ilişki", "İki nicel değişkenin değerleri nokta olarak işaretlenir. Noktalar yukarı doğru diziliyorsa pozitif, aşağı doğru diziliyorsa negatif ilişki vardır; dağınıksa ilişki yoktur.", "Noktaların yönü"),
  _k('s11-mat-01', 2, "İlişki nedensellik değildir", "İki değişkenin birlikte değişmesi, birinin diğerine neden olduğunu göstermez; ikisini birlikte etkileyen üçüncü bir değişken olabilir.", "Korelasyon ≠ nedensellik"),
  _k('s11-mat-05', 1, "Temel trigonometrik denklemler", "sin x = sin a ⟹ x = a + 2kπ veya x = π − a + 2kπ\ncos x = cos a ⟹ x = ±a + 2kπ\ntan x = tan a ⟹ x = a + kπ   (k tam sayı)", "sin: a ve π − a"),
  _k('s11-mat-05', 2, "Trigonometrik fonksiyonların işaretleri", "I. bölge: hepsi +\nII. bölge: yalnız sin +\nIII. bölge: yalnız tan ve cot +\nIV. bölge: yalnız cos +", "Hepsi – sin – tan – cos"),
  _k('s11-mat-06', 1, "Üstel fonksiyon", "f(x) = aˣ (a > 0, a ≠ 1). Tanım kümesi ℝ, görüntü kümesi (0, ∞). a > 1 ise artan, 0 < a < 1 ise azalandır. Grafik (0, 1) noktasından geçer.", "Taban > 1 ise artan"),
  _k('s11-mat-06', 2, "Üstel büyüme ve azalma", "Nüfus artışı, bileşik faiz, bakteri çoğalması üstel büyüme; radyoaktif bozunma ve ilacın vücuttan atılması üstel azalma örneğidir: N(t) = N₀ · aᵗ.", "Sabit oranla çarpılır"),
  _k('s11-mat-08', 1, "Üstel ve logaritmik denklem çözümü", "aˣ = aʸ ⟹ x = y\nlog_a(x) = b ⟹ x = aᵇ\nLogaritmanın içi pozitif olmalıdır; bulunan kökler kontrol edilir.", "Tabanları eşitle"),
  _k('s11-mat-08', 2, "Logaritmik eşitsizlik", "a > 1 ise log_a(x) < log_a(y) ⟺ x < y (yön korunur).\n0 < a < 1 ise yön değişir.\nHer durumda x > 0 ve y > 0 koşulu aranır.", "Taban < 1 ise yön değişir"),
  _k('s11-mat-09', 1, "Fonksiyonlarda dört işlem", "(f + g)(x) = f(x) + g(x)\n(f · g)(x) = f(x) · g(x)\n(f / g)(x) = f(x) / g(x), g(x) ≠ 0\nTanım kümesi, iki fonksiyonun tanım kümelerinin kesişimidir.", "Değerler üzerinden işlem"),
  _k('s11-mat-09', 2, "Bileşke fonksiyonun özellikleri", "(f ∘ g)(x) = f(g(x)); önce g, sonra f uygulanır. Birleşme özelliği vardır, değişme özelliği genellikle yoktur. f ∘ f⁻¹ = I (birim fonksiyon).", "İçten dışa"),
  _k('s11-fiz-01', 1, "Serbest düşme bağıntıları", "İlk hızsız bırakılan cisim yalnızca yer çekimi etkisinde hızlanır (hava direnci önemsiz).\nv = g · t\nh = (1/2) · g · t²\nDüşme süresi kütleden bağımsızdır.", "Kütleden bağımsız"),
  _k('s11-fiz-01', 2, "Yatay atış hareketi", "Yatayda sabit hızlı, düşeyde serbest düşme hareketi birlikte yapılır.\nx = v₀ · t\nh = (1/2) · g · t²\nUçuş süresi yalnızca yüksekliğe bağlıdır.", "Yatay sabit, düşey ivmeli"),
  _k('s11-fiz-03', 1, "Sürtünme kuvveti nelere bağlıdır?", "fs = k · N. Hareketi zorlaştırıcı yöndedir; yüzeylerin cinsine ve dik tepki kuvvetine bağlıdır, temas alanına bağlı değildir. Statik sürtünmenin en büyük değeri kinetik sürtünmeden büyüktür.", "Alana bağlı değil"),
  _k('s11-fiz-03', 2, "Limit hız", "Akışkan içinde düşen cisme etki eden direnç kuvveti hızla artar. Direnç kuvveti ağırlığa eşit olduğunda net kuvvet sıfır olur ve cisim sabit (limit) hızla düşer.", "Direnç = ağırlık"),
  _k('s11-fiz-04', 1, "Düzgün çembersel hareket bağıntıları", "v = 2πr / T\na = v² / r (merkeze yönelik)\nF = m · v² / r\nf = 1 / T\nSürat sabit, hızın yönü sürekli değişir.", "İvme merkeze doğru"),
  _k('s11-fiz-07', 1, "İndüksiyon akımı", "Bir devreden geçen manyetik akı zamanla değiştiğinde devrede akım oluşur (Faraday). Oluşan akım, kendisini doğuran değişime karşı koyacak yöndedir (Lenz).", "Akı değişirse akım oluşur"),
  _k('s11-fiz-07', 2, "Transformatör", "Alternatif gerilimi yükseltir ya da düşürür: Vs / Vp = Ns / Np. Doğru akımda çalışmaz, enerji üretmez. Elektrik enerjisi yüksek gerilimle iletilerek kayıplar azaltılır.", "Sarım oranı = gerilim oranı"),
  _k('s11-fiz-08', 1, "Işık şiddeti, ışık akısı, aydınlanma", "Işık şiddeti (I): kandela (cd)\nIşık akısı (Φ): lümen (lm), Φ = 4πI\nAydınlanma şiddeti (E): lüks (lx), E = I / d² (dik gelen ışınlar için)", "cd – lm – lx"),
  _k('s11-fiz-08', 2, "Aydınlanma şiddetini etkileyen etkenler", "Kaynağın ışık şiddetiyle doğru, uzaklığın karesiyle ters orantılıdır; ışınlar eğik geldikçe azalır: E = (I / d²) · cos α.", "Uzaklık 2 kat → E dörtte bir"),
  _k('s11-fiz-10', 1, "Kırılma", "Işık az yoğun ortamdan çok yoğun ortama geçerken normale yaklaşır, hızı ve dalga boyu azalır; frekansı değişmez. Snell yasası: n₁ · sin θ₁ = n₂ · sin θ₂.", "Yoğuna geçince normale yaklaşır"),
  _k('s11-fiz-10', 2, "Görünür derinlik", "Az yoğun ortamdan çok yoğun ortamdaki cisme bakıldığında cisim olduğundan yakında görünür. Dik bakışta: görünür derinlik = gerçek derinlik · (n_gözlemci / n_cisim).", "Havuz sığ görünür"),
  _k('s11-fiz-11', 1, "Tam yansıma ve fiber optik", "Işık çok yoğun ortamdan az yoğun ortama sınır açısından büyük açıyla gelirse tamamen yansır. Fiber optik kablolar, endoskop ve serap bu olaya dayanır.", "Çoktan aza, sınır açısından büyük"),
  _k('s11-fiz-11', 2, "Prizma ve renklere ayrılma", "Beyaz ışık prizmada renklerine ayrılır. Kırmızı en az, mor en çok kırılır; camın kırılma indisi mor ışık için en büyüktür.", "Mor en çok kırılır"),
  _k('s11-fiz-12', 1, "Mercekler", "İnce kenarlı (yakınsak): ışınları toplar, hipermetropta kullanılır.\nKalın kenarlı (ıraksak): ışınları dağıtır, her zaman sanal ve küçük görüntü verir, miyopta kullanılır.\n1/f = 1/dc + 1/dg", "İnce toplar, kalın dağıtır"),
  _k('s11-fiz-12', 2, "Göz kusurları", "Miyop: uzağı göremez, görüntü retinanın önüne düşer → kalın kenarlı mercek.\nHipermetrop: yakını göremez, görüntü retinanın arkasına düşer → ince kenarlı mercek.\nAstigmat: silindirik mercek.", "Miyop – kalın kenarlı"),
  _k('s11-kim-05', 1, "Nötralleşme", "Asit + baz → tuz + su. Net iyon denklemi: H⁺ + OH⁻ → H₂O. Tam nötralleşmede n(H⁺) = n(OH⁻); tek değerlikli asit ve baz için Ma · Va = Mb · Vb.", "H⁺ ile OH⁻ eşitlenir"),
  _k('s11-kim-05', 2, "Titrasyon", "Derişimi bilinmeyen çözeltinin derişimini, derişimi bilinen çözeltiyle tepkimeye sokarak bulma yöntemidir. Dönüm noktası indikatörün renk değişimiyle belirlenir.", "İndikatör renk değiştirir"),
  _k('s11-kim-06', 1, "Çözünürlük çarpımı nasıl yazılır?", "Doymuş çözeltideki iyon derişimlerinin, katsayıları üs alınarak çarpımıdır. XY için Kçç = s²; XY₂ için Kçç = 4s³. Yalnızca sıcaklıkla değişir.", "Yalnızca sıcaklık değiştirir"),
  _k('s11-kim-06', 2, "Ortak iyon etkisi", "Az çözünen bir tuzun çözünürlüğü, iyonlarından birini içeren çözeltide saf sudakinden daha azdır. Denge katı yönüne kayar; Kçç değişmez.", "Ortak iyon çözünürlüğü azaltır"),
  _k('s11-kim-07', 1, "Mikroplastik ve nanoplastik", "5 mm'den küçük plastik parçacıklar mikroplastik, çok daha küçük olanlar nanoplastiktir. Doğada bozunmaz, besin zincirine girer ve canlılarda birikir.", "5 mm'den küçük"),
  _k('s11-kim-07', 2, "Yeşil hidrojen", "Yenilenebilir enerjiyle suyun elektrolizinden ya da fermantasyon gibi biyolojik yöntemlerle, karbon salımı olmadan üretilen hidrojendir. Yandığında yalnızca su oluşur.", "Karbonsuz yakıt"),
  _k('s11-biy-01', 1, "Tropizma ve nasti", "Tropizma: uyaranın yönüne bağlı yönelim (fototropizma, geotropizma, hidrotropizma).\nNasti: uyaranın yönüne bağlı olmayan hareket (fotonasti, sismonasti, termonasti).", "Yöne bağlı mı?"),
  _k('s11-biy-01', 2, "Bitkisel hormonlar", "Oksin: büyüme, yönelim\nGiberellin: boy uzaması, çimlenme\nSitokinin: hücre bölünmesi, yaşlanmayı geciktirme\nAbsisik asit: uyku hâli, stomaların kapanması\nEtilen: meyve olgunlaşması, yaprak dökümü", "Etilen gazdır"),
  _k('s11-biy-03', 1, "İskelet, kalp ve düz kasın farkları", "İskelet kası: çizgili, istemli, çok çekirdekli, çabuk yorulur.\nKalp kası: çizgili, istemsiz, dallanmış.\nDüz kas: çizgisiz, istemsiz, tek çekirdekli, yavaş kasılır.", "Çizgili – kalp – düz"),
  _k('s11-biy-04', 1, "Aşı ile serum arasındaki fark", "Aktif: vücut kendi antikorunu üretir (hastalığı geçirme, aşı); uzun sürelidir, hafıza hücresi oluşur.\nPasif: hazır antikor alınır (serum, anne sütü); kısa sürelidir.", "Aşı aktif, serum pasif"),
  _k('s11-biy-05', 1, "Homeostazi", "İç ortamın (vücut sıcaklığı, kan şekeri, pH, su ve iyon dengesi) belirli sınırlar içinde kararlı tutulmasıdır. Sinir ve endokrin sistem birlikte düzenler.", "İç denge"),
  _k('s11-biy-05', 2, "Negatif ve pozitif geri bildirim", "Negatif: değişim, kendini azaltacak tepki başlatır (kan şekeri – insülin, vücut sıcaklığı). En yaygın mekanizmadır.\nPozitif: değişim kendini güçlendirir (doğumda oksitosin, kanın pıhtılaşması).", "Negatif dengeler, pozitif artırır"),
  _k('s11-biy-09', 1, "Diabetes mellitus ve diabetes insipidus", "Mellitus: insülin yetersizliği ya da etkisizliği; kan şekeri yükselir, idrarda glikoz görülür.\nİnsipidus: ADH yetersizliği; bol ve seyreltik idrar, kan şekeri normaldir.", "İnsülin – ADH"),
  _k('s11-biy-09', 2, "Hipertansiyon ve obezite", "Hipertansiyon: kan basıncının sürekli yüksek olması; aşırı tuz, stres, hareketsizlik riski artırır.\nObezite: alınan enerjinin harcanandan fazla olması; tip 2 diyabet ve kalp-damar hastalıklarına zemin hazırlar.", "Yaşam tarzı belirleyici"),
  _k('s11-edb-01', 1, "Karagöz", "Gölge oyunudur; oynatan sanatçıya hayalî denir. Bölümleri: mukaddime, muhavere, fasıl, bitiş. Karagöz halkı, Hacivat okumuş kesimi temsil eder.", "Mukaddime – muhavere – fasıl – bitiş"),
  _k('s11-edb-01', 2, "Geleneksel Türk tiyatrosu", "Karagöz, orta oyunu (Pişekâr – Kavuklu), meddah (tek kişilik anlatı), köy seyirlik oyunları. Yazılı metne değil doğaçlamaya dayanır; güldürü ögesi ağır basar.", "Doğaçlama"),
  _k('s11-edb-02', 1, "Mektup türleri", "Özel mektup, edebî mektup, iş mektubu, resmî mektup, açık mektup. Divan edebiyatında mektup derlemelerine münşeat denir; Fuzûlî'nin Şikâyetname'si ünlü bir örnektir.", "Fuzûlî – Şikâyetname"),
  _k('s11-edb-02', 2, "Dilekçe", "Bir isteği ya da şikâyeti resmî kuruma bildiren yazıdır. Tarih, makam adı, kısa ve açık istek metni, ad-soyad, imza ve adres bulunur. Resmî ve saygılı bir dil kullanılır.", "Kısa, açık, resmî"),
  _k('s11-edb-03', 1, "Türk dünyası edebiyatından adlar", "Cengiz Aytmatov (Kırgız): Gün Olur Asra Bedel, Beyaz Gemi\nCengiz Dağcı (Kırım): Korkunç Yıllar\nBahtiyar Vahapzade (Azerbaycan): şiirler\nAbay Kunanbayev (Kazak): şiirler, öğütler", "Yazar – ülke"),
  _k('s11-edb-03', 2, "Ali Şir Nevâî", "15. yüzyılda Çağatay Türkçesinin en büyük şairidir. Muhâkemetü'l-Lugateyn'de Türkçenin Farsçadan üstün olduğunu savunmuş; ilk Türkçe şairler tezkiresi Mecâlisü'n-Nefâis'i yazmıştır.", "Çağatay edebiyatı"),
  _k('s11-edb-04', 1, "Orhun Abideleri", "8. yüzyılda II. Göktürk Devleti döneminde dikilmiştir: Tonyukuk, Kül Tigin, Bilge Kağan yazıtları. Göktürk alfabesiyle yazılmış; Türk adının geçtiği ilk Türkçe metinlerdir.", "Yoluğ Tigin yazmıştır"),
  _k('s11-edb-04', 2, "Dîvânu Lugâti't-Türk", "Kaşgarlı Mahmud'un 11. yüzyılda Araplara Türkçeyi öğretmek için yazdığı sözlüktür. Savlar, sagular, koşuklar ve ilk Türk dünyası haritasını içerir.", "İlk Türkçe sözlük"),
  _k('s11-edb-06', 1, "Biyografi", "Tanınmış bir kişinin hayatının bir başkası tarafından, belgelere dayanarak ve üçüncü kişi ağzından anlatıldığı türdür. Divan edebiyatındaki karşılığı tezkiredir.", "Başkasının hayatı"),
  _k('s11-edb-06', 2, "Tezkire", "Divan edebiyatında şairlerin hayatı ve eserleri hakkında bilgi veren eserdir. İlk örnek: Ali Şir Nevâî – Mecâlisü'n-Nefâis. Anadolu'da ilk: Sehî Bey – Heşt Behişt.", "Şairler biyografisi"),
  _k('s11-edb-07', 1, "Modern Türk tiyatrosu", "İlk tiyatro eseri: Şair Evlenmesi (Şinasi, 1860).\nSahnelenen ilk oyun: Vatan yahut Silistre (Namık Kemal).\nCumhuriyet'te: Haldun Taner, Turgut Özakman, Güngör Dilmen, Orhan Asena.", "Şair Evlenmesi"),
  _k('s11-edb-07', 2, "Epik tiyatro", "Bertolt Brecht'in kuramıdır. Yabancılaştırma tekniğiyle seyircinin oyuna kapılması engellenir, düşünmesi sağlanır. Türk edebiyatında Haldun Taner – Keşanlı Ali Destanı.", "Yabancılaştırma"),
  _k('s11-edb-08', 1, "Küçürek hikâye", "Çok kısa, yoğun ve çarpıcı anlatımlı hikâyedir. Kişi, mekân ve zaman en aza indirilir; ayrıntılar okurun yorumuna bırakılır. Ferit Edgü önemli temsilcisidir.", "Az sözle çok anlam"),
  _k('s11-edb-08', 2, "Küçürek hikâyenin özellikleri", "Birkaç cümle ya da paragraftan oluşabilir; şiirsel ve imgeli bir dil kullanılır; çoğu kez şaşırtıcı bir sonla biter; okurun katılımını ister.", "Yoğunluk ve çarpıcı son"),
  _k('s11-tar-01', 1, "Karlofça ve Pasarofça antlaşmaları", "Karlofça (1699): Batı'da ilk büyük toprak kaybı; Macaristan, Mora, Podolya elden çıktı.\nPasarofça (1718): Belgrad kaybedildi; Lale Devri başladı.\nBelgrad (1739): son kazançlı antlaşma.", "1699 – 1718 – 1739"),
  _k('s11-tar-01', 2, "Küçük Kaynarca Antlaşması (1774)", "Kırım'a bağımsızlık verildi (ilk kez halkı Müslüman bir toprak kaybedildi). Rusya Karadeniz'de ticaret ve Ortodoksları koruma hakkı kazandı.", "Kırım elden çıktı"),
  _k('s11-tar-03', 1, "Sanayi Devrimi", "18. yüzyılda İngiltere'de buhar gücünün üretimde kullanılmasıyla başladı. Sonuçları: fabrika üretimi, işçi sınıfı, kentleşme, ham madde ve pazar arayışı, sömürgeciliğin hızlanması.", "Buhar gücü"),
  _k('s11-tar-03', 2, "Sanayi Devrimi'nin Osmanlı'ya etkisi", "Ucuz Avrupa malları pazarı doldurdu, yerli tezgâhlar kapandı. 1838 Balta Limanı Antlaşması ile Osmanlı açık pazar hâline geldi; dış borçlanma arttı.", "Açık pazar"),
  _k('s11-tar-04', 1, "Fransız İhtilali (1789)", "Yaydığı düşünceler: eşitlik, özgürlük, adalet, milliyetçilik, halk egemenliği. Sonuçları: mutlak krallıklar sarsıldı, İnsan ve Yurttaş Hakları Bildirisi yayımlandı, Yeni Çağ bitti.", "Milliyetçilik"),
  _k('s11-tar-04', 2, "Milliyetçiliğin Osmanlı'ya etkisi", "Çok uluslu yapıyı sarstı. İlk isyan: Sırplar (1804). İlk bağımsızlık: Yunanistan (1829, Edirne Antlaşması). Devlet Osmanlıcılık düşüncesiyle dağılmayı önlemeye çalıştı.", "Sırp isyanı – Yunan bağımsızlığı"),
  _k('s11-tar-06', 1, "Osmanlı'da Batı tarzı ilk okullar", "Mühendishane-i Bahrî-i Hümayun (1773), Mühendishane-i Berrî-i Hümayun (1795), Mekteb-i Tıbbiye (1827), Mekteb-i Harbiye (1834), Mekteb-i Mülkiye (1859), Darülfünun.", "İlki: deniz mühendishanesi"),
  _k('s11-tar-06', 2, "Osmanlı'da sanayileşme çabaları", "19. yüzyılda devlet eliyle fabrikalar (feshane, tophane, kâğıt ve cam fabrikaları) kuruldu, Islah-ı Sanayi Komisyonu oluşturuldu. Sermaye, teknoloji ve uzman eksikliği ile dış rekabet nedeniyle kalıcı olamadı.", "Sermaye ve rekabet engeli"),
  _k('s11-tar-08', 1, "Osmanlı'ya yönelik kitlesel göçler", "93 Harbi (1877-78) ve Balkan Savaşları sonrasında Kafkasya ve Balkanlardan yüz binlerce Türk ve Müslüman Anadolu'ya göç etti; iskân ve geçim sorunları yaşandı.", "Balkanlar ve Kafkasya'dan"),
  _k('s11-tar-08', 2, "Osmanlı'nın insanlık tarihine katkıları", "Farklı din ve kültürleri bir arada yaşatan millet sistemi, vakıf kurumları, mimari eserler (cami, köprü, külliye), hukuk ve yönetim geleneği, el sanatları.", "Hoşgörü ve vakıf"),
  _k('s11-cog-01', 1, "Web tabanlı CBS", "Mekânsal verilerin internet üzerinden görüntülenmesi, sorgulanması ve paylaşılmasıdır. Navigasyon, e-belediye, afet bilgi sistemleri ve parsel sorgulama uygulamaları örnektir.", "Haritaya herkes ulaşır"),
  _k('s11-cog-01', 2, "Mekânsal sorunlar", "Plansız kentleşme, yanlış arazi kullanımı, afet riski, su kıtlığı, çevre kirliliği gibi sorunlar coğrafi analiz ve planlamayla çözülür.", "Sorunun yeri önemli"),
  _k('s11-cog-02', 1, "Türkiye akarsularının özellikleri", "Boyları kısa, akış hızları fazla, rejimleri düzensizdir; hidroelektrik potansiyelleri yüksektir, ulaşıma elverişli değildir. Çoğu kendi sınırlarımızda doğar ve denize dökülür.", "Hızlı ve düzensiz"),
  _k('s11-cog-03', 1, "Şehirlerin etki alanları", "Küresel: İstanbul\nBölgesel: Ankara, İzmir, Bursa, Adana, Gaziantep\nYerel: küçük şehirler\nEtki alanını şehrin fonksiyonlarının gelişmişliği belirler.", "Fonksiyon ne kadar güçlüyse"),
  _k('s11-cog-03', 2, "Plansız şehirleşmenin sonuçları", "Altyapı yetersizliği, çarpık yapılaşma, trafik, konut sorunu, çevre kirliliği, tarım alanlarının yok olması, afet riskinin artması.", "Hızlı göç → plansız büyüme"),
  _k('s11-cog-04', 1, "Tarımda verimi artırma yolları", "Sulama, gübreleme, kaliteli tohum, makineleşme, nöbetleşe ekim, zirai mücadele, çiftçinin eğitilmesi. Türkiye'de verimi en çok artıran etken sulamadır.", "En etkili: sulama"),
  _k('s11-cog-04', 2, "Gıda güvencesi", "Herkesin her zaman yeterli, sağlıklı ve besleyici gıdaya fiziksel ve ekonomik olarak erişebilmesidir. İklim değişikliği, su kıtlığı ve tarım alanlarının azalması tehdit eder.", "Yeterli + erişilebilir + sağlıklı"),
  _k('s11-cog-05', 1, "Türkiye'nin başlıca madenleri", "Bor: Balıkesir, Kütahya, Eskişehir (dünya rezervinin büyük bölümü)\nKrom: Elazığ, Muğla\nDemir: Sivas (Divriği)\nBakır: Kastamonu, Artvin\nTaş kömürü: Zonguldak", "Bor – dünya lideri"),
  _k('s11-cog-06', 1, "Sanayinin kuruluş yerini belirleyen etkenler", "Ham madde, enerji, sermaye, iş gücü, ulaşım, pazar. Türkiye'de sanayi en çok Marmara Bölgesi'nde yoğunlaşmıştır.", "Ham madde – enerji – ulaşım – pazar"),
  _k('s11-cog-06', 2, "Sanayileşmenin mekânsal etkileri", "Olumlu: istihdam, şehirleşme, ulaşım ve hizmetlerin gelişmesi.\nOlumsuz: hava, su ve toprak kirliliği, tarım alanlarının daralması, yoğun göç ve çarpık kentleşme.", "Göç alır, çevreyi zorlar"),
  _k('s11-cog-08', 1, "Türkiye'nin kültürel hinterlandı", "Tarihî, dilsel ve kültürel bağlarla Türkiye'nin etkili olduğu alan: Balkanlar, Kafkasya, Orta Asya, Orta Doğu ve Kuzey Afrika.", "Ortak tarih ve kültür"),
  _k('s11-cog-08', 2, "Türk Devletleri Teşkilatı", "Türk dünyası ülkeleri arasında siyasi, ekonomik ve kültürel iş birliğini geliştiren örgüttür. Üyeleri: Türkiye, Azerbaycan, Kazakistan, Kırgızistan, Özbekistan.", "Türk dünyası iş birliği"),
  _k('s11-fel-01', 1, "Çevre etiği yaklaşımları", "İnsan merkezci: doğa insana yararı ölçüsünde değerlidir.\nCanlı merkezci: tüm canlılar kendi başına değerlidir.\nÇevre merkezci: ekosistemin bütünü (canlı ve cansız) değerlidir.", "İnsan – canlı – çevre"),
  _k('s11-fel-01', 2, "Kuşaklar arası adalet", "Bugünün ihtiyaçlarını karşılarken gelecek kuşakların yaşam hakkını ve kaynaklarını gözetme sorumluluğudur; sürdürülebilirlik düşüncesinin etik temelidir.", "Geleceğe karşı sorumluluk"),
  _k('s11-fel-02', 1, "Teknoloji felsefesinin soruları", "Teknoloji insanı özgürleştirir mi, bağımlı mı kılar? Yapay zekânın kararlarından kim sorumludur? Mahremiyet nasıl korunur? Sanal olan gerçek midir?", "Araç mı, amaç mı?"),
  _k('s11-fel-02', 2, "Yabancılaşma", "İnsanın kendi ürettiği nesnelerin ve düzenin denetimi altına girerek emeğine, çevresine ve kendisine uzaklaşmasıdır. Teknoloji bağımlılığı bu tartışmanın güncel boyutudur.", "Ürettiğinin tutsağı olmak"),
  _k('s11-fel-04', 1, "Felsefe–edebiyat ilişkisi", "İkisi de insanı, hayatı ve anlamı sorgular. Felsefe kavram ve argümanla, edebiyat imge ve kurguyla düşünür. Platon'un diyalogları, Sartre ve Camus'nün romanları iki alanı buluşturur.", "Kavram – imge"),
  _k('s11-fel-04', 2, "Felsefi roman örnekleri", "İbn Tufeyl – Hay bin Yakzan\nVoltaire – Candide\nSartre – Bulantı\nCamus – Yabancı\nDostoyevski – Suç ve Ceza (ahlak sorgulaması)", "Kurguyla felsefe"),
  _k('s11-fel-06', 1, "Doğal hukuk – pozitif hukuk", "Doğal hukuk: insanın doğuştan sahip olduğu, devletten önce var olan haklar (yaşam, özgürlük).\nPozitif hukuk: bir ülkede yürürlükte olan yazılı kurallar.", "Olması gereken – yürürlükteki"),
  _k('s11-fel-06', 2, "Ahlak–hukuk ilişkisi", "Her ikisi de toplumsal düzeni sağlar. Hukukun yaptırımı devlet gücüyle, ahlakın yaptırımı vicdan ve toplumsal kınamayla uygulanır. Adil hukuk ahlaki değerlerle örtüşmelidir.", "Yaptırımı farklı"),
];
